import{_ as a,o as e,c as n,a0 as p}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"upsteam","description":"","frontmatter":{},"headers":[],"relativePath":"git/upsteam.md","filePath":"git/upsteam.md","lastUpdated":1791573371000}'),l={name:"git/upsteam.md"};function r(o,s,t,i,c,u){return e(),n("div",null,[...s[0]||(s[0]=[p(`<h1 id="upsteam" tabindex="-1">upsteam <a class="header-anchor" href="#upsteam" aria-label="Permalink to &quot;upsteam&quot;">​</a></h1><h2 id="关于-fork" tabindex="-1">关于 fork <a class="header-anchor" href="#关于-fork" aria-label="Permalink to &quot;关于 fork&quot;">​</a></h2><blockquote><p>Fork，本身并不是 git 工具中的一个命令，也不是对 git 的扩展，它是在 GitHub 上的概念，是另一种 clone 方式——在服务器端的 clone。而我们通常意义上的 clone，是将远程 repo 复制一份到本地</p></blockquote><p>当你从 GitHub 上 clone 一个 repo 到本地时，除非你已明确声明是这个 repo 的 contributor，否则你是不能向其 pull request 的，此时，该远程的 repo 对于本地 repo 来说，就是 upstream。</p><p>当你从 GitHub 上 fork 一个 repo 之后，再 clone forked repo 到本地，你就可以任意向其 pull request，此时，远程的 repo 就是 origin。</p><p>总结下来：</p><ol><li>如果是 upstream repo，你只可以拉取最新代码，从而保证你本地的仓库与源仓库同步</li><li>如果是 origin repo，就是你自己的 repo（自己创建的，或者 fork 的项目）你可以做 任何推拉操作（pull and push）</li><li>你可以通过 pull request 向 upstream repo 贡献代码</li></ol><h2 id="让-fork-的项目和源项目同步" tabindex="-1">让 fork 的项目和源项目同步 <a class="header-anchor" href="#让-fork-的项目和源项目同步" aria-label="Permalink to &quot;让 fork 的项目和源项目同步&quot;">​</a></h2><blockquote><p>upstream 是一个远程仓库的别名，也可以是其他的名字。origin 也是一个别名。可以配置多个远程仓库</p></blockquote><p>为方便行文，我们将项目的三个别名介绍如下：</p><ul><li>origin：代表远程项目，即 GitHub Fork 项目（克隆自上游项目，即 upstream）</li><li>local 代表本地项目，即电脑上的本地项目（克隆自远程项目）</li><li>upstream：代表上游项目，即被 Fork 的 GitHub 项目</li></ul><p>fork 一个项目后，我们一般是 clone origin 项目到本地开发。local 项目和 origin 项目跟 upstream 是没有什么联系的，那么就不能获取到源仓库最新的代码。</p><p>这时需要给 local 项目设置一个 upstream。也就是再另外配置一个远程仓库。local 仓库可以拉取 upstream 的代码，拉取后可以推送到 origin 仓库</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 增加一个远程仓库</span></span>
<span class="line"><span style="color:#24292E;">$ git remote add upstream </span><span style="color:#6F42C1;">https</span><span style="color:#24292E;">:</span><span style="color:#6A737D;">//github.com/xxx/xxx.git</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 查看远程仓库</span></span>
<span class="line"><span style="color:#24292E;">$ git remote </span><span style="color:#D73A49;">-</span><span style="color:#24292E;">v</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 获取 upstream 的更新（只获取不合并）</span></span>
<span class="line"><span style="color:#24292E;">$ git fetch upstream</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">// 将 upstream 的 master 分支合并到当前分支</span></span>
<span class="line"><span style="color:#24292E;">$ git merge upstream</span><span style="color:#D73A49;">/</span><span style="color:#24292E;">master</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div>`,14)])])}const d=a(l,[["render",r]]);export{b as __pageData,d as default};
